/* sample-photo.js
 * The sample photo for the cover's face detection demo: the official NASA
 * portrait of astronaut Eileen Collins. NASA images are in the public domain.
 *
 * It is kept as data inside a script so that it can be read back from a
 * canvas even when the site is opened straight from disk. Loaded only when a
 * visitor presses "Try a sample photo".
 */
(function (root) {
  'use strict';
  var LJ = (root.LJ = root.LJ || {});
  LJ.samplePhoto = {
    credit: 'Sample photo: astronaut Eileen Collins. NASA, public domain.',
    src: 'data:image/jpeg;base64,'
  };
})(typeof window !== 'undefined' ? window : globalThis);
